import math
from enum import Enum

import rclpy
from geometry_msgs.msg import Point, TwistStamped
from nav_msgs.msg import Odometry
from rclpy.node import Node
from rclpy.qos import QoSProfile, qos_profile_sensor_data


class RobotOdom(Node):
    def __init__(self):
        super().__init__("robot_scan")

        self.scan_sub = self.create_subscription(
            Odometry, "odom", self.scan_callback, qos_profile=qos_profile_sensor_data
        )

        self.cmd_pub = self.create_publisher(TwistStamped, "cmd_vel", 10)
        self.last_print_time = self.get_clock().now()
        self.initial_point = None
        self.checkpoint = Point()
        self.distance_traveled = 0.0

    def scan_callback(self, msg):
        if self.initial_point is None:
            self.initial_point = msg.pose.pose.position
            self.checkpoint = self.initial_point

        self.drive_forward(odom_sub=msg, distance=2.0, speed=0.75)

        now = self.get_clock().now()
        if (now - self.last_print_time).nanoseconds < 1e9:
            return
        self.last_print_time = now
        print(f"distance traveled: {self.distance_traveled:.2f}")
        print(f"x: {msg.pose.pose.position.x:.2f}")
        print(f"y: {msg.pose.pose.position.y:.2f}")
        print(f"heading: {msg.pose.pose.orientation.z:.2f}")

    def test_callback(self, msg):
        cmd = TwistStamped()
        cmd.twist.linear.x = 0.5
        self.cmd_pub.publish(cmd)

    def drive_forward(self, *, odom_sub: Odometry, distance: float, speed: float):
        cmd = TwistStamped()
        if self.point_distance(self.checkpoint, odom_sub.pose.pose.position) < distance:
            cmd.twist.linear.x = speed
        else:
            cmd.twist.linear.x = 0.0
        self.cmd_pub.publish(cmd)
        self.distance_traveled += self.point_distance(
            self.checkpoint, odom_sub.pose.pose.position
        )

    def point_distance(self, point1: Point, point2: Point) -> float:
        return math.sqrt(
            (point1.x - point2.x) ** 2
            + (point1.y - point2.y) ** 2
            + (point1.z - point2.z) ** 2
        )


class DriveState(Enum):
    DRIVE = 0
    TURNING = 1
    FINISHED = False


def main(args=None):
    rclpy.init(args=args)

    odom_driver = RobotOdom()

    rclpy.spin(odom_driver)

    # Destroy the node explicitly
    # (optional - otherwise it will be done automatically
    # when the garbage collector destroys the node object)
    odom_driver.destroy_node()
    rclpy.shutdown()


if __name__ == "__main__":
    main()
